<template><div class="page"><div class="page-head"><div><h2>企业管理</h2><p>维护被分析企业及其部门/负责人归属，数据权限会基于这些字段生效。</p></div><div><el-input v-model="keyword" placeholder="企业名称/编码" style="width:220px;margin-right:8px" @keyup.enter="load"/><el-button @click="load">查询</el-button><el-button type="primary" v-if="auth.has('company:write')" @click="open()">新增企业</el-button></div></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="companyCode" label="编码" width="130"/><el-table-column prop="companyName" label="企业名称" min-width="180"/><el-table-column prop="industry" label="行业"/><el-table-column prop="region" label="区域"/><el-table-column prop="customerLevel" label="客户等级" width="100"/><el-table-column prop="companyScale" label="规模" width="100"/><el-table-column prop="deptId" label="部门ID" width="90"/><el-table-column prop="ownerUserId" label="负责人ID" width="100"/><el-table-column label="操作" width="150" v-if="auth.has('company:write')"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row.id)">删除</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" :title="form.id?'编辑企业':'新增企业'" width="620px"><el-form label-width="90px"><el-row :gutter="12"><el-col :span="12"><el-form-item label="企业编码"><el-input v-model="form.companyCode"/></el-form-item></el-col><el-col :span="12"><el-form-item label="企业名称"><el-input v-model="form.companyName"/></el-form-item></el-col><el-col :span="12"><el-form-item label="行业"><el-input v-model="form.industry"/></el-form-item></el-col><el-col :span="12"><el-form-item label="区域"><el-input v-model="form.region"/></el-form-item></el-col><el-col :span="12"><el-form-item label="客户等级"><el-input v-model="form.customerLevel"/></el-form-item></el-col><el-col :span="12"><el-form-item label="企业规模"><el-input v-model="form.companyScale"/></el-form-item></el-col><el-col :span="12"><el-form-item label="部门ID"><el-input-number v-model="form.deptId" :min="1" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="负责人ID"><el-input-number v-model="form.ownerUserId" :min="1" style="width:100%"/></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import{ref,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api}from'../api';import{useAuthStore}from'../stores/auth';const auth=useAuthStore();const rows=ref([]),keyword=ref(''),loading=ref(false),visible=ref(false);const blank=()=>({companyCode:'',companyName:'',industry:'',region:'',customerLevel:'A',companyScale:'中型',deptId:2,ownerUserId:4,status:1});const form=ref(blank());async function load(){loading.value=true;try{rows.value=(await api.companies({keyword:keyword.value||undefined}))||[]}finally{loading.value=false}}function open(r){form.value=r?{...r}:blank();visible.value=true}async function save(){if(!form.value.companyCode||!form.value.companyName)return ElMessage.warning('请填写编码和名称');form.value.id?await api.updateCompany(form.value.id,form.value):await api.createCompany(form.value);ElMessage.success('保存成功');visible.value=false;load()}async function remove(id){await ElMessageBox.confirm('确定删除该企业？','提示',{type:'warning'});await api.deleteCompany(id);ElMessage.success('已删除');load()}onMounted(load)</script>
